    {
        "name": "Aflatoxicosis",
        "name_ja": "アフラトキシン中毒",
        "symptoms": {"appetite_loss", "lethargy", "liver_enlargement", "diarrhea", "weight_loss", "immunosuppression", "sudden_death"},
        "description": "Aflatoxicosis is a toxicological condition caused by exposure to harmful substances.",
        "description_ja": "汚染飼料中のアスペルギルス・フラバスが産生するアフラトキシンによる肝毒性。",
        "urgency": "high",
        "recommended_tests": ["liver_panel", "bile_acids", "feed_analysis", "histopathology"],
        "causes": "Toxic liver damage from aflatoxins produced by Aspergillus flavus in contaminated feed.",
        "causes_ja": "鳥におけるアフラトキシン中毒の原因: 汚染飼料中のアスペルギルス・フラバスが産生するアフラトキシンによる肝毒性。",
        "pathophysiology": "Toxic liver damage from aflatoxins produced by Aspergillus flavus in contaminated feed. Fungal organisms establish infection through spore inhalation, direct inoculation, or mucosal colonization. Hyphae or yeast forms penetrate tissues via enzymatic degradation and mechanical pressure, eliciting a granulomatous inflammatory response. Immunocompromised individuals are particularly susceptible. The infection may remain localized or disseminate hematogenously to distant organs. Chronic infections can lead to fibrosis, tissue remodeling, and progressive organ dysfunction.",
        "pathophysiology_ja": "アフラトキシン中毒は鳥における真菌感染症である。真菌は胞子吸入、直接接種、または粘膜コロニー形成を通じて感染を確立する。菌糸または酵母形態が酵素分解と機械的圧力により組織に侵入し、肉芽腫性炎症反応を惹起する。免疫不全個体は特に感受性が高い。感染は局所にとどまるか、血行性に遠隔臓器へ播種される可能性がある。慢性感染は線維化、組織リモデリング、進行性臓器機能障害を引き起こしうる。",
        "treatment": "Treatment of aflatoxicosis in bird requires systemic antifungal therapy. Azole antifungals (fluconazole, itraconazole, ketoconazole) or amphotericin B may be used depending on the organism and severity. Treatment duration is typically prolonged (weeks to months) to ensure complete clearance. Topical antifungal agents may be used adjunctively for superficial infections. Environmental decontamination reduces reinfection risk. Monitor hepatic function during prolonged azole therapy.",
        "treatment_ja": "鳥におけるアフラトキシン中毒の治療には全身性抗真菌薬療法が必要である。アゾール系抗真菌薬（フルコナゾール、イトラコナゾール、ケトコナゾール）またはアムホテリシンBが菌種と重症度に応じて使用される。治療期間は完全な除菌のため通常長期間（数週間〜数ヶ月）を要する。表在性感染には局所抗真菌剤を併用する。環境消毒により再感染リスクを低減する。長期アゾール療法中は肝機能をモニタリングする。",
        "prevention": "Prevention includes removing access to toxic substances, using pet-safe products, proper storage of medications and chemicals, and educating owners about common toxins.",
        "prevention_ja": "アフラトキシン中毒の予防には適切な環境湿度・温度の維持、良好な換気、過密の回避、定期的な清掃・消毒、罹患個体の隔離、適切な栄養による免疫機能の維持が含まれる。",
        "prognosis": "",
        "prognosis_ja": "アフラトキシン中毒の予後は適切な管理により一般的にやや良好〜良好である。早期診断された症例の多くは治療に良好に反応する。慢性例や再発例では長期管理が必要だが、概ね許容できるQOLを維持できる。定期的なモニタリングにより合併症の早期発見・対処が可能となる。",
        "onset_pattern": {"acute"},
        "age_predisposition": {"adult", "puppy", "senior", "young"},
    },
