    {
        "name": "Papilloma",
        "name_ja": "乳頭腫",
        "symptoms": {"oral_plaques", "tissue_protruding_from_vent", "skin_lesions", "regurgitation", "foul_smelling_discharge"},
        "description": "Papilloma is a clinical condition requiring veterinary evaluation, diagnosis, and appropriate treatment.",
        "description_ja": "パピローマウイルスによる良性上皮性腫瘤で、口腔、総排泄腔、皮膚に発生。",
        "urgency": "moderate",
        "recommended_tests": ["biopsy", "histopathology", "PCR_papillomavirus"],
        "causes": "Multifactorial etiology associated with Papilloma; may involve genetic predisposition, environmental factors, infectious agents, and/or metabolic dysfunction.",
        "causes_ja": "鳥における乳頭腫の原因: ウイルス病原体による感染。直接接触、飛沫・空気感染、媒介物、ベクター媒介が感染経路。免疫抑制、ストレス、過密飼育、ワクチン未接種が感受性を高める。",
        "pathophysiology": "The pathological process involves tissue injury, inflammatory response, and progressive functional impairment. Without intervention, compensatory mechanisms may be overwhelmed, leading to clinical deterioration.",
        "pathophysiology_ja": "乳頭腫は鳥におけるウイルス感染症である。ウイルスは特定の受容体を介して宿主細胞に侵入し、細胞内機構を利用して複製する。直接的な細胞変性効果（細胞溶解、アポトーシス、標的臓器の組織壊死）を引き起こす。自然免疫（インターフェロン、NK細胞）および適応免疫（抗体、細胞性免疫）の宿主免疫応答が免疫病理に寄与することがある。ウイルス血症により病原体が複数の臓器系に播種される可能性があり、免疫抑制により二次的な細菌・真菌感染のリスクが高まる。",
        "treatment": "Treatment should be tailored to the specific condition and includes appropriate medical or surgical intervention, supportive care, pain management, and regular monitoring of treatment response.",
        "treatment_ja": "鳥における乳頭腫の治療は主に支持療法であり、多くのウイルス感染症には特異的抗ウイルス薬がない。輸液療法により水分補給と電解質補正を行う。解熱鎮痛薬で発熱と不快感を管理する。広域抗菌薬で二次細菌感染を予防・治療する。食欲不振時の補助給餌を含む栄養サポートが不可欠である。免疫賦活剤やインターフェロンが有効な場合がある。感受性個体への伝播防止のため罹患個体を隔離する。",
        "prevention": "Prevention includes appropriate husbandry, balanced nutrition, regular veterinary examinations, stress reduction, and prompt treatment of early signs of illness.",
        "prevention_ja": "乳頭腫の予防にはワクチン接種（利用可能な場合）、新規・病気動物の隔離、厳格なバイオセキュリティ対策、適切な消毒プロトコル、既知のキャリアや汚染環境との接触回避が含まれる。",
        "prognosis": "",
        "prognosis_ja": "乳頭腫の予後は適切な管理により一般的にやや良好〜良好である。早期診断された症例の多くは治療に良好に反応する。慢性例や再発例では長期管理が必要だが、概ね許容できるQOLを維持できる。定期的なモニタリングにより合併症の早期発見・対処が可能となる。",
        "onset_pattern": {"acute", "subacute"},
        "age_predisposition": {"adult", "puppy", "senior", "young"},
    },
