    {
        "name": "Feather Mites",
        "name_ja": "羽毛ダニ",
        "symptoms": {"feather_loss", "itching", "feather_damage", "restlessness", "poor_feather_quality"},
        "description": "Feather Mites is a parasitic condition that causes clinical signs ranging from subclinical to severe systemic disease.",
        "description_ja": "羽軸に寄生する外部ダニ感染で、羽毛損傷を引き起こす。",
        "urgency": "low",
        "recommended_tests": ["feather_exam_microscopy", "skin_scraping", "scotch_tape_test"],
        "causes": "Caused by parasitic organisms infecting dermatological tissue. Transmission occurs via ingestion of infective stages (eggs, oocysts, larvae), direct contact, vector-borne routes, or percutaneous penetration. Predisposing factors include poor sanitation, outdoor exposure, immunosuppression, and stress. In bird, the varies by species diet may expose them to specific parasitic life cycles.",
        "causes_ja": "皮膚組織に感染する寄生虫が原因。感染期（卵・オーシスト・幼虫）の経口摂取・直接接触・ベクター・経皮侵入で伝播。不衛生・屋外曝露・免疫抑制・ストレスが素因。鳥の食性が特定の寄生虫生活環への曝露を増加させうる。",
        "pathophysiology": "The parasite establishes infection in dermatological tissue of bird through ingestion, skin penetration, or vector-mediated transmission. Parasitic organisms damage host tissue through direct mechanical injury, nutrient competition, and immunopathological responses. Eosinophilic and granulomatous inflammation develops around parasitic stages. Chronic infection leads to tissue fibrosis and organ dysfunction. The avian with air sacs and unique respiratory system characteristics of bird may influence parasite lifecycle completion and host susceptibility.",
        "pathophysiology_ja": "寄生虫は経口摂取・皮膚穿通・ベクター媒介により鳥の皮膚組織に感染を確立する。寄生体は直接的な機械的損傷・栄養競合・免疫病理学的反応を通じて宿主組織を損傷する。寄生体段階の周囲に好酸球性・肉芽腫性炎症が発生する。慢性感染は組織線維化と臓器機能障害に至る。",
        "treatment": "Treatment includes appropriate antiparasitic medication, environmental decontamination, and supportive care. Repeat treatments may be necessary to address lifecycle stages.",
        "treatment_ja": "鳥における羽毛ダニの治療は、原因に対する特異的療法と支持療法の組み合わせで行う。輸液療法・栄養支持・疼痛管理（種に適した鎮痛薬）・環境最適化が基本。特異的治療は診断に基づき、抗菌薬・駆虫薬・抗真菌薬・外科的介入・支持療法が含まれうる。エキゾチック動物専門獣医師への相談を推奨。",
        "prevention": "Prevention includes regular parasite screening and treatment, environmental sanitation, quarantine of new animals, and avoiding overcrowding.",
        "prevention_ja": "予防には適切な飼育管理（適切な食事・清潔な環境・最適な温湿度）；定期的な獣医師の健康診断；新規動物の検疫；ストレス軽減；種特異的予防措置が含まれる",
        "prognosis": "Prognosis depends on severity, timeliness of treatment, and response to therapy. Early intervention generally improves outcomes.",
        "prognosis_ja": "適切な駆虫薬治療で予後は一般的に良好。重度感染や免疫不全鳥では予後不良となりうる。環境消毒と再感染予防が長期的な予後改善に重要。定期的な糞便検査と予防的駆虫が推奨される。",
        "onset_pattern": {"acute", "subacute"},
        "age_predisposition": {"adult", "puppy", "senior", "young"},
    },
