    {
        "name": "Coccidia",
        "name_ja": "コクシジウム症",
        "symptoms": {"diarrhea", "bloody_droppings", "weight_loss", "lethargy", "dehydration", "fluffed_feathers"},
        "description": "Coccidia is a parasitic condition that causes clinical signs ranging from subclinical to severe systemic disease.",
        "description_ja": "原虫性腸管寄生虫で、特に若鳥やストレス下の鳥に腸炎を引き起こす。",
        "urgency": "moderate",
        "recommended_tests": ["fecal_float", "fecal_direct_smear", "fecal_PCR"],
        "causes": "Caused by parasitic infestation; transmitted through contaminated environment, direct contact, or ingestion of intermediate hosts.",
        "causes_ja": "消化器系組織に感染する寄生虫が原因。感染期（卵・オーシスト・幼虫）の経口摂取・直接接触・ベクター・経皮侵入で伝播。不衛生・屋外曝露・免疫抑制・ストレスが素因。鳥の食性が特定の寄生虫生活環への曝露を増加させうる。",
        "pathophysiology": "The pathological process involves tissue injury, inflammatory response, and progressive functional impairment. Without intervention, compensatory mechanisms may be overwhelmed, leading to clinical deterioration.",
        "pathophysiology_ja": "寄生虫は経口摂取・皮膚穿通・ベクター媒介により鳥の消化器系組織に感染を確立する。寄生体は直接的な機械的損傷・栄養競合・免疫病理学的反応を通じて宿主組織を損傷する。寄生体段階の周囲に好酸球性・肉芽腫性炎症が発生する。慢性感染は組織線維化と臓器機能障害に至る。",
        "treatment": "Treatment includes appropriate antiparasitic medication, environmental decontamination, and supportive care. Repeat treatments may be necessary to address lifecycle stages.",
        "treatment_ja": "鳥におけるコクシジウムの治療は、原因に対する特異的療法と支持療法の組み合わせで行う。輸液療法・栄養支持・疼痛管理（種に適した鎮痛薬）・環境最適化が基本。特異的治療は診断に基づき、抗菌薬・駆虫薬・抗真菌薬・外科的介入・支持療法が含まれうる。エキゾチック動物専門獣医師への相談を推奨。",
        "prevention": "Prevention includes regular parasite screening and treatment, environmental sanitation, quarantine of new animals, and avoiding overcrowding.",
        "prevention_ja": "予防には適切な飼育管理（適切な食事・清潔な環境・最適な温湿度）；定期的な獣医師の健康診断；新規動物の検疫；ストレス軽減；種特異的予防措置が含まれる",
        "prognosis": "Prognosis depends on severity, timeliness of treatment, and response to therapy. Early intervention generally improves outcomes.",
        "prognosis_ja": "適切な駆虫薬治療で予後は一般的に良好。重度感染や免疫不全鳥では予後不良となりうる。環境消毒と再感染予防が長期的な予後改善に重要。定期的な糞便検査と予防的駆虫が推奨される。",
        "onset_pattern": {"acute", "subacute"},
        "age_predisposition": {"adult", "puppy", "senior", "young"},
    },
