    {
        "name": "Avian Erythroblastosis (Leukosis)",
        "name_ja": "鳥赤芽球症（白血病）",
        "symptoms": {"abdominal_distension", "lethargy", "pale_comb", "weakness", "weight_loss"},
        "description": "Avian Erythroblastosis (Leukosis) is a clinical condition requiring veterinary evaluation, diagnosis, and appropriate treatment.",
        "description_ja": "レトロウイルスによる造血系の腫瘍性疾患で、貧血と臓器浸潤を引き起こす。",
        "urgency": "high",
        "recommended_tests": ["CBC", "blood_smear", "histopathology", "bone_marrow_biopsy"],
        "causes": "Retrovirus-induced neoplastic disease of the hematopoietic system causing anemia and organ infiltration.",
        "causes_ja": "鳥における鳥赤芽球症（白血病）の原因: レトロウイルスによる造血系の腫瘍性疾患で、貧血と臓器浸潤を引き起こす。",
        "pathophysiology": "Avian Erythroblastosis (Leukosis) is caused by viral infection. Retrovirus-induced neoplastic disease of the hematopoietic system causing anemia and organ infiltration. The virus enters host cells through specific receptor-mediated mechanisms, hijacking cellular machinery for replication. This leads to direct cytopathic effects including cell lysis, apoptosis, and tissue necrosis in target organs. The host immune response—involving both innate (interferons, NK cells) and adaptive (antibody, cell-mediated) pathways—may contribute to immunopathology. Viremia can disseminate the pathogen to multiple organ systems, and immunosuppression may predispose to secondary bacterial or fungal infections.",
        "pathophysiology_ja": "鳥赤芽球症（白血病）は鳥におけるウイルス感染症である。ウイルスは特定の受容体を介して宿主細胞に侵入し、細胞内機構を利用して複製する。直接的な細胞変性効果（細胞溶解、アポトーシス、標的臓器の組織壊死）を引き起こす。自然免疫（インターフェロン、NK細胞）および適応免疫（抗体、細胞性免疫）の宿主免疫応答が免疫病理に寄与することがある。ウイルス血症により病原体が複数の臓器系に播種される可能性があり、免疫抑制により二次的な細菌・真菌感染のリスクが高まる。",
        "treatment": "Treatment of avian erythroblastosis (leukosis) in bird is primarily supportive, as most viral infections lack specific antiviral therapy. Fluid therapy maintains hydration and corrects electrolyte imbalances. Antipyretics and analgesics manage fever and discomfort. Broad-spectrum antibiotics prevent or treat secondary bacterial infections. Nutritional support—including assisted feeding if anorexic—is essential. Immunostimulants or interferons may be beneficial in some cases. Isolation of affected individuals prevents transmission to susceptible contacts.",
        "treatment_ja": "鳥における鳥赤芽球症（白血病）の治療は主に支持療法であり、多くのウイルス感染症には特異的抗ウイルス薬がない。輸液療法により水分補給と電解質補正を行う。解熱鎮痛薬で発熱と不快感を管理する。広域抗菌薬で二次細菌感染を予防・治療する。食欲不振時の補助給餌を含む栄養サポートが不可欠である。免疫賦活剤やインターフェロンが有効な場合がある。感受性個体への伝播防止のため罹患個体を隔離する。",
        "prevention": "Prevention includes appropriate husbandry, balanced nutrition, regular veterinary examinations, stress reduction, and prompt treatment of early signs of illness.",
        "prevention_ja": "鳥赤芽球症（白血病）の予防にはワクチン接種（利用可能な場合）、新規・病気動物の隔離、厳格なバイオセキュリティ対策、適切な消毒プロトコル、既知のキャリアや汚染環境との接触回避が含まれる。",
        "prognosis": "",
        "prognosis_ja": "鳥赤芽球症（白血病）の予後は適切な管理により一般的にやや良好〜良好である。早期診断された症例の多くは治療に良好に反応する。慢性例や再発例では長期管理が必要だが、概ね許容できるQOLを維持できる。定期的なモニタリングにより合併症の早期発見・対処が可能となる。",
        "onset_pattern": {"acute", "subacute"},
        "age_predisposition": {"adult", "puppy", "senior", "young"},
    },
