    {
        "name": "Proventricular Ulceration",
        "name_ja": "腺胃潰瘍",
        "symptoms": {"appetite_loss", "dark_droppings", "lethargy", "regurgitation", "weight_loss"},
        "description": "Proventricular Ulceration is an erosive lesion of tissue requiring treatment to promote healing and prevent complications.",
        "description_ja": "感染、ストレス、重金属中毒による腺胃粘膜の潰瘍形成。",
        "urgency": "high",
        "recommended_tests": ["endoscopy", "radiography", "heavy_metal_panel", "biopsy"],
        "causes": "Ulceration of the proventricular mucosa due to infection, stress, or heavy metal toxicosis.",
        "causes_ja": "鳥における腺胃潰瘍の原因: 感染、ストレス、重金属中毒による腺胃粘膜の潰瘍形成。",
        "pathophysiology": "Proventricular Ulceration is a toxicological condition. Ulceration of the proventricular mucosa due to infection, stress, or heavy metal toxicosis. Toxic injury occurs through ingestion, inhalation, or dermal absorption of the offending agent. The toxin disrupts cellular processes through specific mechanisms such as enzyme inhibition, receptor interference, oxidative damage, or direct cytotoxicity. Target organs vary by toxin but commonly include the liver (biotransformation), kidneys (excretion), nervous system, and GI tract. Dose-dependent effects range from subclinical changes to fulminant organ failure.",
        "pathophysiology_ja": "腺胃潰瘍は鳥における中毒性疾患である。有害物質の経口摂取、吸入、または経皮吸収により中毒障害が生じる。毒素は酵素阻害、受容体干渉、酸化的損傷、直接的な細胞毒性などの特定のメカニズムを通じて細胞プロセスを障害する。標的臓器は毒素により異なるが、肝臓（生体内変換）、腎臓（排泄）、神経系、消化管が一般的である。用量依存的に無症候性変化から劇症型臓器不全まで幅広い影響を及ぼす。",
        "treatment": "Treatment of proventricular ulceration in bird requires rapid decontamination and supportive care. If ingestion was recent, emesis induction (where safe for the species) or gastric lavage may reduce absorption. Activated charcoal adsorbs many toxins. Specific antidotes should be administered when available (e.g., vitamin K1 for anticoagulant rodenticides, N-acetylcysteine for acetaminophen). Aggressive IV fluid therapy supports renal excretion and maintains perfusion. Monitor and treat organ-specific damage (hepatic, renal, neurological).",
        "treatment_ja": "鳥における腺胃潰瘍の治療には迅速な除染と支持療法が必要である。摂取直後であれば催吐（種にとって安全な場合）または胃洗浄により吸収を低減する。活性炭は多くの毒素を吸着する。特異的解毒剤がある場合は投与する（例：抗凝固性殺鼠剤にビタミンK1、アセトアミノフェンにN-アセチルシステイン）。積極的な輸液療法で腎排泄を促進し灌流を維持する。臓器特異的障害（肝、腎、神経）をモニタリングし治療する。",
        "prevention": "Prevention includes appropriate husbandry, balanced nutrition, regular veterinary examinations, stress reduction, and prompt treatment of early signs of illness.",
        "prevention_ja": "腺胃潰瘍の予防には有毒物質へのアクセス制限・除去、ペット安全な製品の使用、環境からの有毒植物の除去、薬剤・化学物質の適切な保管、屋外アクセス時の監視、種固有の中毒に関する飼い主教育が必要である。",
        "prognosis": "",
        "prognosis_ja": "腺胃潰瘍の予後は適切な管理により一般的にやや良好〜良好である。早期診断された症例の多くは治療に良好に反応する。慢性例や再発例では長期管理が必要だが、概ね許容できるQOLを維持できる。定期的なモニタリングにより合併症の早期発見・対処が可能となる。",
        "onset_pattern": {"acute", "subacute"},
        "age_predisposition": {"adult", "puppy", "senior", "young"},
    },
