    {
        "name": "Contact Dermatitis",
        "name_ja": "接触性皮膚炎",
        "symptoms": {"feather_loss", "pruritus", "redness", "skin_lesions", "swollen_feet"},
        "description": "Contact Dermatitis is a dermatological condition affecting the skin, coat, or integumentary system.",
        "description_ja": "清掃用化学物質や粗い止まり木などの刺激物との接触による皮膚炎。",
        "urgency": "low",
        "recommended_tests": ["clinical_examination", "environmental_review", "skin_biopsy"],
        "causes": "Skin irritation from contact with irritants such as cleaning chemicals or rough perches.",
        "causes_ja": "鳥における接触性皮膚炎の原因: 清掃用化学物質や粗い止まり木などの刺激物との接触による皮膚炎。",
        "pathophysiology": "Contact Dermatitis is a dermatological condition. Skin irritation from contact with irritants such as cleaning chemicals or rough perches. The skin pathology involves disruption of the epidermal barrier, dermal inflammation, or adnexal dysfunction. Compromised barrier function permits transepidermal water loss, allergen penetration, and microbial colonization. Inflammatory mediators (histamine, prostaglandins, cytokines) drive pruritus, erythema, and secondary excoriation. Chronic disease leads to epidermal hyperplasia, lichenification, hyperpigmentation, and fibrosis.",
        "pathophysiology_ja": "接触性皮膚炎は鳥における皮膚疾患である。表皮バリア、真皮炎症、または付属器機能の障害を伴う。バリア機能の低下により経表皮水分喪失、アレルゲン浸透、微生物コロニー形成が促進される。炎症メディエーター（ヒスタミン、プロスタグランジン、サイトカイン）が掻痒、紅斑、二次的な擦過傷を駆動する。慢性疾患では表皮過形成、苔癬化、色素沈着、線維化が生じる。",
        "treatment": "",
        "treatment_ja": "鳥における接触性皮膚炎の治療は原因への対処、適切な支持療法、臨床徴候の管理を行う。種に適した薬物療法、食事の最適化、環境調整が主要な治療要素である。定期的なフォローアップにより治療効果を確認し用量調整を行う。",
        "prevention": "Prevention of contact dermatitis includes appropriate husbandry, balanced species-specific nutrition, regular veterinary health checks, stress minimization, maintaining clean living conditions, and prompt attention to early clinical signs.",
        "prevention_ja": "接触性皮膚炎の予防には適切な飼育管理、種に合ったバランスの取れた栄養、定期的な健康診断、ストレスの最小化、清潔な生活環境の維持、初期臨床徴候への迅速な対応が含まれる。",
        "prognosis": "",
        "prognosis_ja": "接触性皮膚炎の予後は適切な管理により一般的にやや良好〜良好である。早期診断された症例の多くは治療に良好に反応する。慢性例や再発例では長期管理が必要だが、概ね許容できるQOLを維持できる。定期的なモニタリングにより合併症の早期発見・対処が可能となる。",
        "onset_pattern": {"acute", "subacute"},
        "age_predisposition": {"adult", "puppy", "senior", "young"},
    },
    {
        "name": "Preen Gland Abscess (Uropygial Gland)",
        "name_ja": "尾脂腺膿瘍",
        "symptoms": {"discharge_from_gland", "feather_matting", "pain_on_palpation", "swelling_at_tail_base"},
        "description": "Preen Gland Abscess (Uropygial Gland) is a localized collection of purulent material requiring drainage and antimicrobial therapy.",
        "description_ja": "尾脂腺の感染または閉塞による膿瘍形成。",
        "urgency": "moderate",
        "recommended_tests": ["fine_needle_aspirate", "bacterial_culture", "cytology"],
        "causes": "Caused by bacterial infection, often secondary to immunosuppression, stress, poor husbandry, or wound contamination.",
        "causes_ja": "鳥における尾脂腺膿瘍の原因: 尾脂腺の感染または閉塞による膿瘍形成。",
        "pathophysiology": "The pathological process involves tissue injury, inflammatory response, and progressive functional impairment. Without intervention, compensatory mechanisms may be overwhelmed, leading to clinical deterioration.",
        "pathophysiology_ja": "尾脂腺膿瘍は鳥における細菌感染症である。病原菌は付着因子を通じて組織にコロニーを形成し、毒素産生、酵素分泌、免疫回避戦略などの病原性メカニズムを介して侵入する。好中球浸潤、サイトカイン放出、補体活性化を含む炎症カスケードが生じる。組織損傷は細菌の直接作用と宿主の炎症反応の両方に起因する。菌種と宿主の免疫状態に応じて、膿瘍形成、敗血症、または慢性肉芽腫性炎症が発生しうる。",
        "treatment": "",
        "treatment_ja": "鳥における尾脂腺膿瘍の治療には、可能であれば培養感受性試験に基づく標的抗菌薬療法が必要である。結果待ちの間は経験的広域抗菌薬を開始する。抗菌薬治療期間は感染の排除と耐性予防に十分な期間とする。膿瘍や壊死組織には外科的排膿またはデブリードマンが必要な場合がある。支持療法として輸液、鎮痛薬、抗炎症薬、栄養サポートを行う。",
        "prevention": "Prevention includes appropriate husbandry, balanced nutrition, regular veterinary examinations, stress reduction, and prompt treatment of early signs of illness.",
        "prevention_ja": "尾脂腺膿瘍の予防には適切な衛生管理・消毒、利用可能なワクチン接種、創傷の迅速な処置、ストレス軽減、適切な換気、感染動物の隔離が含まれる。",
        "prognosis": "",
        "prognosis_ja": "尾脂腺膿瘍の予後は適切な管理により一般的にやや良好〜良好である。早期診断された症例の多くは治療に良好に反応する。慢性例や再発例では長期管理が必要だが、概ね許容できるQOLを維持できる。定期的なモニタリングにより合併症の早期発見・対処が可能となる。",
        "onset_pattern": {"acute"},
        "age_predisposition": {"adult", "puppy", "senior", "young"},
    },
    {
        "name": "Preen Gland Adenoma/Carcinoma",
        "name_ja": "尾脂腺腺腫・癌",
        "symptoms": {"bleeding", "swelling_at_tail_base", "ulcerated_masses", "weight_loss"},
        "description": "Preen Gland Adenoma/Carcinoma is a neoplastic condition characterized by abnormal cell proliferation that may be benign or malignant.",
        "description_ja": "尾脂腺の良性（腺腫）または悪性（癌）腫瘍。",
        "urgency": "moderate",
        "recommended_tests": ["fine_needle_aspirate", "biopsy", "histopathology", "staging_radiography"],
        "causes": "Caused by neoplastic cell proliferation; etiology is often multifactorial including genetic predisposition, age, hormonal influences, and environmental factors.",
        "causes_ja": "鳥における尾脂腺腺腫・癌の原因: 尾脂腺の良性（腺腫）または悪性（癌）腫瘍。",
        "pathophysiology": "Accumulated genetic mutations lead to uncontrolled cell proliferation, evasion of apoptosis, and potential metastatic spread. Tumor growth causes tissue compression, invasion, and paraneoplastic effects.",
        "pathophysiology_ja": "尾脂腺腺腫・癌は鳥における腫瘍性疾患である。癌遺伝子、腫瘍抑制遺伝子、DNA修復機構における遺伝子変異の蓄積により腫瘍性形質転換が生じる。制御不能な細胞増殖により腫瘍が形成され、局所組織への浸潤・破壊の可能性がある。悪性腫瘍はリンパ行性または血行性に転移しうる。高カルシウム血症、悪液質、免疫調節障害などの腫瘍随伴症候群が原発腫瘍に伴い、罹患率に寄与することがある。",
        "treatment": "Treatment options include surgical excision, chemotherapy, radiation therapy, and palliative care depending on tumor type, location, and staging. Supportive care and pain management are essential.",
        "treatment_ja": "鳥における尾脂腺腺腫・癌の治療は腫瘍の種類、部位、病期に依存する。アクセス可能な固形腫瘍には十分なマージンを確保した外科的切除が第一選択である。全身性腫瘍、不完全切除、転移性疾患には化学療法が適応となりうる。放射線療法は局所的な腫瘍制御を提供できる。根治療法が困難な場合は疼痛管理、栄養サポート、QOL維持に焦点を当てた緩和ケアを行う。",
        "prevention": "Prevention is limited for most neoplastic conditions. Regular health examinations facilitate early detection. Spaying/neutering may reduce risk of hormone-dependent tumors.",
        "prevention_ja": "尾脂腺腺腫・癌の予防は限定的であるが、ホルモン依存性腫瘍軽減のための避妊・去勢手術、既知の発癌物質の回避、早期発見のための定期健診、適正体型の維持、該当する場合は遺伝的素因軽減のための責任ある繁殖が含まれる。",
        "prognosis": "",
        "prognosis_ja": "尾脂腺腺腫・癌の予後は適切な管理により一般的にやや良好〜良好である。早期診断された症例の多くは治療に良好に反応する。慢性例や再発例では長期管理が必要だが、概ね許容できるQOLを維持できる。定期的なモニタリングにより合併症の早期発見・対処が可能となる。",
        "onset_pattern": {"chronic"},
        "age_predisposition": {"adult", "senior"},
    },
