    {
        "name": "Psittacine Poxvirus (Canarypox Variant)",
        "name_ja": "オウム目痘瘡ウイルス（カナリア痘変異型）",
        "symptoms": {"skin_lesions", "crusty_lesions_on_face", "oral_plaques", "conjunctivitis", "lethargy"},
        "description": "Psittacine Poxvirus (Canarypox Variant) is a viral disease that may cause acute or chronic illness with variable clinical presentation.",
        "description_ja": "オウム目に特異的なポックスウイルス変異型で、重度の皮膚・ジフテリア様病変を引き起こす。",
        "urgency": "high",
        "recommended_tests": ["biopsy", "PCR_poxvirus", "histopathology"],
        "causes": "Species-specific poxvirus variant causing severe cutaneous and diphtheritic lesions in psittacines.",
        "causes_ja": "鳥におけるオウム目痘瘡ウイルス（カナリア痘変異型）の原因: オウム目に特異的なポックスウイルス変異型で、重度の皮膚・ジフテリア様病変を引き起こす。",
        "pathophysiology": "Psittacine Poxvirus (Canarypox Variant) is caused by viral infection. Species-specific poxvirus variant causing severe cutaneous and diphtheritic lesions in psittacines. The virus enters host cells through specific receptor-mediated mechanisms, hijacking cellular machinery for replication. This leads to direct cytopathic effects including cell lysis, apoptosis, and tissue necrosis in target organs. The host immune response—involving both innate (interferons, NK cells) and adaptive (antibody, cell-mediated) pathways—may contribute to immunopathology. Viremia can disseminate the pathogen to multiple organ systems, and immunosuppression may predispose to secondary bacterial or fungal infections.",
        "pathophysiology_ja": "オウム目痘瘡ウイルス（カナリア痘変異型）は鳥におけるウイルス感染症である。ウイルスは特定の受容体を介して宿主細胞に侵入し、細胞内機構を利用して複製する。直接的な細胞変性効果（細胞溶解、アポトーシス、標的臓器の組織壊死）を引き起こす。自然免疫（インターフェロン、NK細胞）および適応免疫（抗体、細胞性免疫）の宿主免疫応答が免疫病理に寄与することがある。ウイルス血症により病原体が複数の臓器系に播種される可能性があり、免疫抑制により二次的な細菌・真菌感染のリスクが高まる。",
        "treatment": "Treatment is primarily supportive, including fluid therapy, nutritional support, and secondary infection prevention. Antiviral agents may be used where available and indicated.",
        "treatment_ja": "鳥におけるオウム目痘瘡ウイルス（カナリア痘変異型）の治療は主に支持療法であり、多くのウイルス感染症には特異的抗ウイルス薬がない。輸液療法により水分補給と電解質補正を行う。解熱鎮痛薬で発熱と不快感を管理する。広域抗菌薬で二次細菌感染を予防・治療する。食欲不振時の補助給餌を含む栄養サポートが不可欠である。免疫賦活剤やインターフェロンが有効な場合がある。感受性個体への伝播防止のため罹患個体を隔離する。",
        "prevention": "Prevention includes vaccination where available, quarantine of new animals, biosecurity measures, proper hygiene, and avoiding contact with infected animals.",
        "prevention_ja": "オウム目痘瘡ウイルス（カナリア痘変異型）の予防にはワクチン接種（利用可能な場合）、新規・病気動物の隔離、厳格なバイオセキュリティ対策、適切な消毒プロトコル、既知のキャリアや汚染環境との接触回避が含まれる。",
        "prognosis": "",
        "prognosis_ja": "オウム目痘瘡ウイルス（カナリア痘変異型）の予後は適切な管理により一般的にやや良好〜良好である。早期診断された症例の多くは治療に良好に反応する。慢性例や再発例では長期管理が必要だが、概ね許容できるQOLを維持できる。定期的なモニタリングにより合併症の早期発見・対処が可能となる。",
        "onset_pattern": {"acute", "subacute"},
        "age_predisposition": {"adult", "puppy", "senior", "young"},
    },
